import{Component}from"@theme/component";import{debounce,fetchConfig}from"@theme/utilities";import{cartPerformance}from"@theme/performance";class CartNote extends Component{#t=null;updateCartNote=debounce(async t=>{if(!(t.target instanceof HTMLTextAreaElement))return;const e=t.target.value;this.#t&&this.#t.abort();const o=new AbortController;this.#t=o;try{const t=fetchConfig("json",{body:JSON.stringify({note:e})});await fetch(Theme.routes.cart_update_url,{...t,signal:o.signal})}catch(t){}finally{this.#t=null,cartPerformance.measureFromEvent("note-update:user-action",t)}},200)}customElements.get("cart-note")||customElements.define("cart-note",CartNote);